addTerms([
 {id:"sacrifice",t:"Sacrifice",la:"sacrificium",d:"Sacraments",b:"An offering to God of something visible, by a priest, in acknowledgement of God's supreme lordship, in which something is done to the thing offered.",p:"Offering sacrifice belongs to the natural law (ST II-II q.85 a.1). \"Sacrifices are properly so called when something is done to the thing offered to God\" (q.85 a.3 ad 3, paraphrased). Its elements: a priest, a victim, an offering to God alone, and a change in the victim.",ex:"Abel's lambs; the Passover lamb; Christ on the Cross; the Mass.",where:"II-II q.85; III q.48 a.3",ccc:"2099–2100",conf:"Any act of self-denial or generosity (sacrifice in a loose, moral sense).",rel:["immolation","oblation","religion-virtue"],lesson:"ms1",alias:["sacrifice","sacrifices","victim"]},
 {id:"four-ends",t:"Four ends of sacrifice",la:"finis latreuticus, eucharisticus, propitiatorius, impetratorius",d:"Sacraments",b:"Every true sacrifice is offered for adoration, thanksgiving, propitiation (atonement for sin) and petition.",p:"The Mass fulfils all four perfectly because it is Christ's own offering (Trent, Session 22, ch. 2 and canon 3; Mediator Dei, 1947). Adoration and thanksgiving are owed to God for what he is and gives; propitiation and petition because we are sinners in need.",ex:"Offering a Mass in thanksgiving for a birth, or for the soul of someone who has died.",where:"Trent, Session 22",ccc:"1359–1361, 1367",conf:"Four separate kinds of Mass.",rel:["sacrifice","propitiation"],lesson:"ms1",alias:["ends of the mass","four ends","latreutic","impetratory","impetration"]},
 {id:"immolation",t:"Immolation",la:"immolatio",d:"Sacraments",b:"The act by which the victim of a sacrifice is slain or changed so as to be given over to God. On Calvary it was bloody and real; in the Mass it is unbloody, sacramental or \"mystical\".",p:"From Latin mola, the salted meal sprinkled on a victim. Trent: in the Mass is \"contained and immolated in an unbloody manner the same Christ\" who offered himself once in a bloody manner on the altar of the Cross (Session 22, ch. 2). Theologians differ on how to explain the immolation: by the separate consecration of the two species (mystical immolation), by a change of state, or by the Church's offering of the once-immolated Victim.",ex:"The words \"This is my body… This is the chalice of my blood\" spoken separately over bread and wine.",where:"III q.83 a.1; Trent, Session 22",ccc:"1366–1367",conf:"Christ suffering or dying again in each Mass.",rel:["sacrifice","oblation","double-consecration"],lesson:"ms4",alias:["immolation","immolated","mystical immolation","unbloody immolation","unbloody manner"]},
 {id:"oblation",t:"Oblation",la:"oblatio",d:"Sacraments",b:"The offering of a gift or victim to God. In the Mass, Christ offers himself through the priest, and the Church offers Christ and herself with him.",p:"Distinguished from immolation (the change in the victim). Maurice de la Taille argued that the essence of the Mass is the Church's oblation of the Victim immolated once on Calvary (Mysterium Fidei, 1921). The Roman Canon: \"we offer to your glorious majesty… a pure victim, a holy victim, a spotless victim\" (Unde et memores).",ex:"The offertory and, above all, the anamnesis-offering after the consecration.",where:"Trent, Session 22, ch. 1",ccc:"1368",conf:"Only the collection of money.",rel:["immolation","sacrifice"],lesson:"ms4",alias:["oblation","offering of the victim"]},
 {id:"propitiation",t:"Propitiatory sacrifice",la:"sacrificium propitiatorium",d:"Sacraments",b:"A sacrifice that turns away God's just anger by making satisfaction for sin, so that he grants grace and the gift of repentance.",p:"Trent defines that the Mass is \"truly propitiatory\": by it God, appeased, grants grace and the gift of penitence and forgives even grave sins (Session 22, ch. 2, paraphrased; canon 3). It does not forgive mortal sin directly as confession does; it obtains the grace to repent.",ex:"A Mass offered for a sinner's conversion or for the dead.",where:"Trent, Session 22, ch. 2, canon 3",ccc:"1371, 1414",conf:"Bribing an angry God.",rel:["four-ends","satisfaction"],lesson:"ms3",alias:["propitiatory","propitiation","truly propitiatory"]},
 {id:"double-consecration",t:"Double (separate) consecration",la:"consecratio duplex",d:"Sacraments",b:"The consecration of bread and wine separately, which by the force of the words places Christ's body under one sign and his blood under another, sacramentally showing his death.",p:"By the power of the words (vi verborum) the body is under the species of bread and the blood under the species of wine; by natural concomitance the whole Christ is under each (ST III q.76 a.1–2). The separate signs represent the Passion, in which blood was separated from body (cf. III q.74 a.1; q.76 a.2 ad 1). Pius XII: the separate species symbolise the separation of his body and blood (Mediator Dei, 1947). Hence it is forbidden to consecrate one without the other (CIC 927).",ex:"The two elevations: the Host, then the chalice.",where:"III q.76 a.2; q.83 a.1",ccc:"1353, 1366",conf:"Two separate sacrifices.",rel:["immolation","concomitance","transubstantiation"],lesson:"ms4",alias:["double consecration","separate consecration","two species","vi verborum"]},
 {id:"concomitance",t:"Concomitance",la:"concomitantia",d:"Sacraments",b:"The whole living Christ, body, blood, soul and divinity, is present under each species, because in the risen Christ these are never separated.",p:"By the force of the words only the body is signified under the bread, but by real concomitance the blood, soul and divinity are there too (ST III q.76 a.1; Trent, Session 13, ch. 3). So Communion under one kind gives the whole Christ (Trent, Session 21).",ex:"Receiving only the Host still means receiving Christ entirely.",where:"III q.76 a.1–2",ccc:"1377, 1390",conf:"Half of Christ in the Host and half in the chalice.",rel:["transubstantiation","double-consecration"],lesson:"ms5",alias:["concomitance","whole christ under each species","body blood soul and divinity"]},
 {id:"anamnesis",t:"Anamnesis (memorial)",la:"memoria",d:"Liturgy",b:"The liturgical memorial in which a saving event is not only recalled but made present; also the prayer after the consecration that remembers the Passion, Resurrection and Ascension and offers the Victim.",p:"In the biblical sense, remembering makes present: \"this day shall be for a memorial\" (Exodus 12:14). \"In the liturgical celebration of these events, they become in a certain way present and real\" (CCC 1363). Hence \"Do this in memory of me\" grounds the sacrificial character of the Eucharist.",ex:"\"Therefore, O Lord, as we celebrate the memorial of his Death and Resurrection, we offer you…\" (Eucharistic Prayer II).",where:"Luke 22:19; 1 Cor 11:24–25",ccc:"1362–1366",conf:"Merely thinking about a past event.",rel:["oblation"],lesson:"ms3",alias:["anamnesis","memorial","do this in memory"]},
 {id:"mass-fruits",t:"Fruits of the Mass",la:"fructus missae",d:"Sacraments",b:"The benefits of the Mass applied to people: the general fruit for the whole Church and world, the special (ministerial) fruit applied by the priest to his intention, and the most special fruit for the priest himself.",p:"The sacrifice is of infinite value in itself because of the Victim and Priest, but its application is finite, according to God's will and the devotion of those for whom it is offered (ST III q.79 a.5 and a.7 ad 2). Hence Masses are offered for particular intentions, living and dead (Trent, Session 22, canon 3; CIC 901, 945–958).",ex:"Having a Mass offered for a deceased grandmother.",where:"III q.79 a.5, a.7",ccc:"1371, 1414",conf:"Buying grace with a stipend.",rel:["four-ends","propitiation"],lesson:"ms7",alias:["fruits of the mass","mass intention","mass intentions","stipend","offering for a mass"]}
]);

